public static ClientSessionModel getClientSession(String code, KeycloakSession session, RealmModel realm) {
    try {
        String[] parts = code.split("\\.");
        String id = parts[1];
        return session.sessions().getClientSession(realm, id);
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid code format, must contain at least one dot", e);
    } catch (NullPointerException e) {
        throw new IllegalArgumentException("Code cannot be null", e);
    }
}
